window.CODE_SAMPLES = {"signal": [{"title": "Pipeline orchestration", "path": "Suhani_PBEL_3.0-main/source code/src/pipeline.py", "code": "\"\"\"\nOrchestrates the full PART 1 + PART 2 pipeline end-to-end and writes\nresults to data/processed/ so the API can serve them without recomputing\non every request. Run this after dropping a new dataset into data/raw/,\nor on a schedule in production.\n\n    python -m src.pipeline\n\"\"\"\nimport logging\nimport pandas as pd\n\nfrom src.utils import allow_unverified_ssl_for_nltk_downloads\nallow_unverified_ssl_for_nltk_downloads()\n\nfrom src.config import DATA_PROCESSED\nfrom src.data.ingest import load_email_data, load_insider_labels\nfrom src.data.store import write_df\nfrom src.data.anonymize import anonymize_dataframe, pseudonymize_user\nfrom src.data.validate import validate_email_df\nfrom src.features.linguistic_features import extract_features_df\nfrom src.features.stylometry import extract_stylometry_df\nfrom src.features.network_features import extract_network_features_df\nfrom src.features.baseline_engine import BaselineEngine\nfrom src.features.drift_scoring import score_drift_df, aggregate_user_risk\nfrom src.features.trajectory import compute_trajectory_df\nfrom src.models.unsupervised.anomaly_detection import fit_isolation_forest, fit_dbscan_clusters\nfrom src.governance.audit_log import log_event\nfrom src.governance.bias_audit import audit_drift_by_style_proxy\nfrom src.governance.openscale_monitor import build_monitor_snapshot, compare_to_previous_snapshot\nfrom src.governance.alert_suppression import apply_context_aware_suppression\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n\ndef run_pipeline() -> dict:\n    logger.info(\"=== Starting pipeline run ===\")\n\n    raw = load_email_data()\n    validate_email_df(raw)\n\n    # Network-drift features (contact_degree, interaction_concentration) are\n    # computed from raw to/cc/bcc *before* anonymization, keyed to raw's own\n    # row index: anonymize_dataframe()'s single-string HMAC over the whole\n    # semicolon-joined `to` field is meant for the single-address `user`/\n    # `from` columns, not a multi-recipient list, so computing network\n    # features first and re-aligning by index afterward avoids depending on\n    # that column post-anonymization. Only the two resulting numeric columns\n    # are carried forward — no raw address ever leaves this block.\n    net_feats = extract_network_features_df(raw, user_col=\"user\", date_col=\"date\")\n    net_cols = net_feats[[\"contact_degree\", \"interaction_concentration\"]]\n\n    anon = anonymize_dataframe(raw)\n    anon = anon.join(net_cols)  # index-aligned; consent-filtered rows keep only their own values\n    feats = extract_features_df(anon)\n    feats = extract_stylometry_df(feats)\n\n    engine = BaselineEngine()\n    z_df = engine.replay(feats)\n    scored = score_drift_df(z_df)\n\n    user_risk = aggregate_user_risk(scored)\n\n    # Trajectory: fits each user's own chronological drift-score sequence\n    # (numpy.polyfit) to get trend_slope + acceleration, merged onto the\n    # existing level-based risk table rather than replacing it — see\n    # src/features/trajectory.py.\n    trajectory = compute_trajectory_df(scored, user_col=\"user\", date_col=\"date\")\n    user_risk = user_risk.merge(trajectory, on=\"user\", how=\"left\")\n\n    _, _, msg_with_anomaly = fit_isolation_forest(scored)\n    _, _, user_with_clusters = fit_dbscan_clusters(user_risk)\n\n    # Org-wide monitoring snapshot is computed here (rather than only in the\n    # governance-addenda block below) because context-aware alert\n    # suppression needs to know *before* persisting user_risk whether this\n    # run shows a correlated, organization-wide shift — see\n    # governance/alert_suppression.py. Kept in its own try/except, same\n    # graceful-degradation pattern as the rest of this function: a snapshot\n    # failure should never block the core scoring pipeline from persisting.\n    org_wide_shift_detected = False\n    snapshot = None\n    try:\n        snapshot = build_monitor_snapshot(scored, user_with_clusters)\n        snapshot_comparison = compare_to_previous_snapshot(snapshot)\n        org_wide_shift_detected = bool(snapshot_comparison[\"alerts\"])\n        if org_wide_shift_detected:\n            logger.warning(f\"Monitoring snapshot flagged org-wide feature drift: {snapshot_comparison['alerts']}\")\n    except Exception as e:\n        logger.warning(f\"Monitoring snapshot step failed, continuing without it: {e}\")\n\n    # Context-aware alert suppression: gates individual escalation on\n    # relative standing among this run's own (possibly also-elevated)\n    # population, raising the bar further when the whole org shifted\n    # together — see governance/alert_suppression.py.\n    user_with_clusters = apply_context_aware_suppression(\n        user_with_clusters, org_wide_shift_detected=org_wide_shift_detected\n    )\n\n    # persist for the API layer to read without recomputation\n    # NOTE: must write msg_with_anomaly (not the original `scored`) — it's the\n    # frame with IsolationForest's anomaly_score/is_anomaly columns attached.\n    # Writing `scored` here silently dropped those columns before they ever\n    # reached the API, even though the model ran and logged its results above.\n    #\n    # write_df (src/data/store.py) writes to the live Neon `scored_messages`/\n    # `user_risk` tables when DATABASE_URL is set — not just a local CSV —\n    # since a deployed API (e.g. on Vercel) has no persistent local disk to\n    # read data/processed/*.csv back from between requests or deploys.\n    write_df(msg_with_anomaly, \"scored_messages\")\n    write_df(user_with_clusters, \"user_risk\")\n\n    labels = load_insider_labels()\n    if labels is not None:\n        labels = labels.copy()\n        labels[\"user\"] = labels[\"user\"].map(pseudonymize_user)\n        labels.to_csv(DATA_PROCESSED / \"user_labels_pseudonymized.csv\", index=False)\n\n    top_flagged = user_with_clusters.sort_values(\"avg_drift_score\", ascending=False).head(10)\n    for _, row in top_flagged.iterrows():\n        log_event(\n            \"drift_flagged\",\n            row[\"user\"],\n            {\"avg_drift_score\": row[\"avg_drift_score\"], \"flagged_message_rate\": row[\"flagged_message_rate\"]},\n        )\n\n    # Governance addendum: a per-run fairness check on writing-style proxies\n    # — see governance/bias_audit.py. (The org-wide monitoring snapshot is\n    # computed earlier now, since alert suppression depends on it — see\n    # above.)\n    try:\n        bias_report = audit_drift_by_style_proxy(scored)\n        if bias_report[\"proxies_with_disparity_over_1_5x\"]:\n            logger.warning(\n                f\"Bias audit flagged possible disparity in: \"\n                f\"{bias_report['proxies_with_disparity_over_1_5x']} — see data/processed/reports/bias_audit.md\"\n            )\n    except Exception as e:\n        logger.warning(f\"Bias audit step failed, continuing without it: {e}\")\n\n    logger.info(f\"=== Pipeline run complete: {len(scored)} messages, {len(user_risk)} users ===\")\n    return {\n        \"n_messages\": len(scored),\n        \"n_users\": len(user_risk),\n        \"processed_dir\": str(DATA_PROCESSED),\n        \"org_wide_shift_detected\": org_wide_shift_detected,\n    }\n\n\nif __name__ == \"__main__\":\n    result = run_pipeline()\n    print(result)\n"}, {"title": "FastAPI application", "path": "Suhani_PBEL_3.0-main/source code/src/api/app.py", "code": "\"\"\"\nPART 2 — FastAPI entrypoint.\n\nRun locally with:\n    uvicorn src.api.app:app --reload --host 0.0.0.0 --port 8000\n\nServes both the JSON API (mounted routers) and the static frontend\ndashboard (frontend/) so the whole thing is one deployable unit — matches\nthe IBM Code Engine deployment target (single container).\n\"\"\"\nimport logging\nfrom pathlib import Path\n\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.staticfiles import StaticFiles\n\nfrom src.config import ROOT_DIR\nfrom src.api.routes import users, drift, assistant, governance, agent\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\napp = FastAPI(\n    title=\"Insider Threat NLP — Behavioral Drift Detection API\",\n    description=(\n        \"Detects linguistic/behavioral drift in internal communications as a \"\n        \"privacy-respecting insider-risk signal. All user-facing data is \"\n        \"pseudonymous by design — see docs/ETHICS_AND_PRIVACY.md.\"\n    ),\n    version=\"0.1.0\",\n)\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],  # tighten in production to the actual frontend origin\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"],\n)\n\napp.include_router(users.router, prefix=\"/api/users\", tags=[\"users\"])\napp.include_router(drift.router, prefix=\"/api/drift\", tags=[\"drift\"])\napp.include_router(assistant.router, prefix=\"/api/assistant\", tags=[\"watsonx-assistant\"])\napp.include_router(governance.router, prefix=\"/api/governance\", tags=[\"governance\"])\napp.include_router(agent.router, prefix=\"/api/agent\", tags=[\"agentic-ai\"])\n\n\n@app.get(\"/health\")\ndef health():\n    return {\"status\": \"ok\"}\n\n\n# Mounted LAST and at \"/\": StaticFiles(html=True) greedily serves \"/\" and any\n# unmatched path as index.html, so it must be registered after every API\n# route (and after /health) to avoid shadowing them.\nFRONTEND_DIR = ROOT_DIR / \"frontend\"\nif FRONTEND_DIR.exists():\n    app.mount(\"/\", StaticFiles(directory=str(FRONTEND_DIR), html=True), name=\"frontend\")\n"}, {"title": "Storage abstraction", "path": "Suhani_PBEL_3.0-main/source code/src/data/store.py", "code": "\"\"\"\nStorage helpers for pipeline outputs (scored_messages, user_risk).\n\nMirrors the same fallback pattern as src/data/ingest.py: when DATABASE_URL\nis set, pipeline outputs are written to / read from live Neon Postgres\ntables, so the deployed API (e.g. on Vercel, whose filesystem is read-only\nand stateless between requests/deploys) can actually serve them. When\nDATABASE_URL is unset, falls back to local CSVs under data/processed/, so\n`python -m src.pipeline` + local `uvicorn` still works exactly as before\nfor anyone not using Neon.\n\nThis is why the \"Pipeline has not been run yet\" error shows up on Vercel\neven after running the pipeline locally: local data/processed/*.csv files\nnever make it to the deployed function, since each serverless invocation\ngets its own throwaway filesystem. Writing to Neon instead fixes that,\nbecause Neon is a real persistent database reachable from anywhere.\n\"\"\"\nimport logging\nfrom typing import Optional\n\nimport pandas as pd\n\nfrom src.config import DATA_PROCESSED, DATABASE_URL\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n\ndef _get_engine():\n    if not DATABASE_URL:\n        return None\n    try:\n        from sqlalchemy import create_engine\n        return create_engine(DATABASE_URL)\n    except ImportError:\n        logger.warning(\n            \"DATABASE_URL is set but sqlalchemy/psycopg2-binary aren't \"\n            \"installed (pip install -r requirements.txt) — falling back to \"\n            \"local CSV storage under data/processed/.\"\n        )\n        return None\n\n\ndef write_df(df: pd.DataFrame, table_name: str) -> None:\n    \"\"\"\n    Persists df as `table_name`. If DATABASE_URL is set, writes (replaces)\n    a Neon Postgres table of the same name — this is what the deployed API\n    reads from. Always ALSO writes a local CSV under data/processed/ so\n    local development without Neon keeps working unchanged.\n    \"\"\"\n    csv_path = DATA_PROCESSED / f\"{table_name}.csv\"\n    df.to_csv(csv_path, index=False)\n    logger.info(f\"Wrote {len(df)} rows to local {csv_path}\")\n\n    engine = _get_engine()\n    if engine is None:\n        return\n    try:\n        df.to_sql(table_name, engine, if_exists=\"replace\", index=False)\n        logger.info(f\"Wrote {len(df)} rows to Neon table '{table_name}'.\")\n    except Exception as e:\n        logger.warning(\n            f\"Failed to write '{table_name}' to Neon ({e}) — local CSV was \"\n            \"still saved, so local dev is unaffected.\"\n        )\n\n\ndef read_df(table_name: str) -> Optional[pd.DataFrame]:\n    \"\"\"\n    Reads `table_name`. Tries Neon first if DATABASE_URL is set; falls back\n    to the local CSV under data/processed/ if Neon is unset/unreachable/the\n    table doesn't exist there yet. Returns None if neither source has data\n    (i.e. the pipeline genuinely hasn't been run anywhere yet).\n    \"\"\"\n    engine = _get_engine()\n    if engine is not None:\n        try:\n            df = pd.read_sql(f'SELECT * FROM \"{table_name}\"', engine)\n            return df\n        except Exception as e:\n            logger.warning(\n                f\"Could not read '{table_name}' from Neon ({e}) — falling \"\n                \"back to local CSV.\"\n            )\n\n    csv_path = DATA_PROCESSED / f\"{table_name}.csv\"\n    if csv_path.exists():\n        return pd.read_csv(csv_path)\n    return None\n"}, {"title": "Sliding-window statistics", "path": "Suhani_PBEL_3.0-main/source code/src/dsa/sliding_window.py", "code": "\"\"\"\nDSA: fixed-size sliding window with O(1) amortized rolling mean/variance.\n\nWhy not just call np.mean()/np.std() on a slice every time?\nRecomputing mean/variance from scratch on every new message is O(w) per\nupdate where w = window size. Across thousands of users each producing\nhundreds of messages, that's O(n * w) total. This structure updates\nincrementally in O(1) per insertion (amortized), giving O(n) total —\nthe difference matters once this runs per-user, per-day, at CERT-dataset\nscale (tens of thousands of employees).\n\nApproach: a deque holds the last `w` values. On insert we update a running\nsum and running sum-of-squares in O(1); when the window overflows we evict\nthe oldest value and adjust the same running totals in O(1). Mean and\n(population) variance are then simple arithmetic, no rescans.\n\nThis is a simplified two-pass-free variant of Welford's algorithm adapted\nfor a *bounded* window (Welford's classic form is for an unbounded stream).\n\"\"\"\nfrom collections import deque\n\n\nclass SlidingWindowStats:\n    def __init__(self, window_size: int):\n        if window_size <= 0:\n            raise ValueError(\"window_size must be positive\")\n        self.window_size = window_size\n        self._values = deque(maxlen=window_size)\n        self._sum = 0.0\n        self._sum_sq = 0.0\n\n    def push(self, value: float) -> None:\n        \"\"\"Add a new value, evicting the oldest if the window is full. O(1) amortized.\"\"\"\n        if len(self._values) == self.window_size:\n            oldest = self._values[0]  # will be auto-evicted by deque's maxlen\n            self._sum -= oldest\n            self._sum_sq -= oldest * oldest\n        self._values.append(value)\n        self._sum += value\n        self._sum_sq += value * value\n\n    @property\n    def count(self) -> int:\n        return len(self._values)\n\n    @property\n    def mean(self) -> float:\n        if not self._values:\n            return 0.0\n        return self._sum / len(self._values)\n\n    @property\n    def variance(self) -> float:\n        \"\"\"Population variance, clamped to >= 0 to guard against fp drift.\"\"\"\n        n = len(self._values)\n        if n == 0:\n            return 0.0\n        mean = self.mean\n        var = (self._sum_sq / n) - (mean * mean)\n        return max(var, 0.0)\n\n    @property\n    def std(self) -> float:\n        return self.variance ** 0.5\n\n    def z_score(self, value: float) -> float:\n        \"\"\"How many std-devs `value` is from this window's mean. 0.0 std -> 0.0 (no drift signal yet).\"\"\"\n        std = self.std\n        if std == 0.0:\n            return 0.0\n        return (value - self.mean) / std\n\n    def is_full(self) -> bool:\n        return len(self._values) == self.window_size\n\n    def snapshot(self) -> dict:\n        return {\n            \"count\": self.count,\n            \"mean\": round(self.mean, 4),\n            \"std\": round(self.std, 4),\n            \"window_size\": self.window_size,\n        }\n\n\nif __name__ == \"__main__\":\n    # quick self-test\n    w = SlidingWindowStats(window_size=5)\n    for v in [1, 2, 3, 4, 5, 100]:  # 100 should push out the \"1\" and spike the mean\n        w.push(v)\n    print(w.snapshot())\n    print(\"z-score of 100 given current window:\", w.z_score(100))\n"}, {"title": "Aho-Corasick matcher", "path": "Suhani_PBEL_3.0-main/source code/src/dsa/trie_phrase_matcher.py", "code": "\"\"\"\nDSA: Aho-Corasick automaton for multi-pattern phrase matching.\n\nWhy: we scan every message against ~20-100+ urgency / social-engineering\nphrases (config.URGENCY_PHRASES). Naively that's O(n_phrases * len(text))\nper message via repeated substring search. Aho-Corasick builds a trie of\nall patterns plus failure links, so a message of length m is scanned in\nO(m + matches) *regardless of how many phrases we're looking for* — this\nis what lets the phrase list grow to hundreds of entries without slowing\ndown per-message scanning.\n\nImplementation: classic Aho-Corasick (trie + BFS-built failure links +\noutput links), built once at startup from config.URGENCY_PHRASES and\nreused across all messages.\n\"\"\"\nfrom collections import deque\nfrom typing import List, Dict, Tuple\n\n\nclass _Node:\n    __slots__ = (\"children\", \"fail\", \"output\")\n\n    def __init__(self):\n        self.children: Dict[str, \"_Node\"] = {}\n        self.fail: \"_Node\" = None\n        self.output: List[str] = []  # phrases that end at this node\n\n\nclass AhoCorasick:\n    def __init__(self, phrases: List[str]):\n        self.root = _Node()\n        self.root.fail = self.root\n        self._phrases = [p.lower() for p in phrases]\n        self._build_trie()\n        self._build_failure_links()\n\n    def _build_trie(self):\n        for phrase in self._phrases:\n            node = self.root\n            for ch in phrase:\n                node = node.children.setdefault(ch, _Node())\n            node.output.append(phrase)\n\n    def _build_failure_links(self):\n        queue = deque()\n        for child in self.root.children.values():\n            child.fail = self.root\n            queue.append(child)\n\n        while queue:\n            current = queue.popleft()\n            for ch, child in current.children.items():\n                queue.append(child)\n                fail_node = current.fail\n                while fail_node is not self.root and ch not in fail_node.children:\n                    fail_node = fail_node.fail\n                child.fail = fail_node.children.get(ch, self.root) if fail_node is not child else self.root\n                if child.fail is child:\n                    child.fail = self.root\n                # merge output (a shorter phrase can be a suffix of a longer one)\n                child.output += child.fail.output\n\n    def scan(self, text: str) -> List[Tuple[str, int]]:\n        \"\"\"Return list of (phrase, end_index) matches in text. O(len(text) + matches).\"\"\"\n        text = text.lower()\n        node = self.root\n        matches: List[Tuple[str, int]] = []\n\n        for i, ch in enumerate(text):\n            while node is not self.root and ch not in node.children:\n                node = node.fail\n            node = node.children.get(ch, self.root)\n            for phrase in node.output:\n                matches.append((phrase, i))\n        return matches\n\n    def urgency_score(self, text: str) -> float:\n        \"\"\"\n        Simple normalized score: number of distinct matched phrases / total\n        phrases in the lexicon, capped at 1.0. Used as one input feature to\n        the risk model, not a verdict on its own.\n        \"\"\"\n        matches = self.scan(text)\n        if not matches or not self._phrases:\n            return 0.0\n        distinct = len({m[0] for m in matches})\n        return min(distinct / max(len(self._phrases), 1) * 5, 1.0)  # scaled so 1-2 hits already register\n\n\nif __name__ == \"__main__\":\n    from src.config import URGENCY_PHRASES\n    ac = AhoCorasick(URGENCY_PHRASES)\n    sample = \"Hey, this is urgent — please wire transfer the funds ASAP and don't tell anyone.\"\n    print(ac.scan(sample))\n    print(\"urgency_score:\", ac.urgency_score(sample))\n"}, {"title": "Top-K heap", "path": "Suhani_PBEL_3.0-main/source code/src/dsa/top_k_heap.py", "code": "\"\"\"\nDSA: bounded min-heap for maintaining the Top-K riskiest users.\n\nWhy: after scoring N users (N can be tens of thousands in CERT-scale data),\nwe usually only want the top K (e.g. 10-50) to show an analyst. Sorting\nall N scores is O(N log N). A bounded min-heap of size K gives O(N log K)\ninstead — push every score, and whenever the heap exceeds size K, pop the\nsmallest. Since K << N, this is a meaningful win at scale and is the\nstandard \"top-K of a stream\" pattern.\n\"\"\"\nimport heapq\nfrom dataclasses import dataclass, field\nfrom typing import List\n\n\n@dataclass(order=True)\nclass RiskEntry:\n    score: float\n    user_id: str = field(compare=False)\n    details: dict = field(compare=False, default_factory=dict)\n\n\nclass TopKRiskHeap:\n    def __init__(self, k: int):\n        if k <= 0:\n            raise ValueError(\"k must be positive\")\n        self.k = k\n        self._heap: List[RiskEntry] = []\n\n    def push(self, user_id: str, score: float, details: dict = None) -> None:\n        entry = RiskEntry(score=score, user_id=user_id, details=details or {})\n        if len(self._heap) < self.k:\n            heapq.heappush(self._heap, entry)\n        elif score > self._heap[0].score:\n            heapq.heapreplace(self._heap, entry)\n        # else: score too low to make the cut, O(1) discard\n\n    def top_k(self) -> List[RiskEntry]:\n        \"\"\"Return entries sorted descending by risk score.\"\"\"\n        return sorted(self._heap, key=lambda e: e.score, reverse=True)\n\n\nif __name__ == \"__main__\":\n    heap = TopKRiskHeap(k=3)\n    for uid, score in [(\"u1\", 0.2), (\"u2\", 0.9), (\"u3\", 0.5), (\"u4\", 0.95), (\"u5\", 0.1)]:\n        heap.push(uid, score)\n    for e in heap.top_k():\n        print(e.user_id, e.score)\n"}, {"title": "LRU baseline cache", "path": "Suhani_PBEL_3.0-main/source code/src/dsa/lru_cache_baselines.py", "code": "\"\"\"\nDSA: LRU cache for per-user baseline objects.\n\nWhy: drift_scoring.py needs each user's SlidingWindowStats baseline on\nevery scored message. Rebuilding a baseline from scratch (rescanning that\nuser's history) on every lookup is expensive; keeping *all* users'\nbaselines resident in memory forever doesn't scale either. An LRU cache\ngives O(1) get/put and bounds memory to `capacity` most-recently-active\nusers, which matches real traffic patterns (most activity comes from a\nsmall recently-active subset of employees at any given time).\n\nImplemented with an OrderedDict for O(1) average get/put + O(1) move-to-end.\n\"\"\"\nfrom collections import OrderedDict\nfrom typing import Any, Optional\n\n\nclass LRUCache:\n    def __init__(self, capacity: int = 512):\n        if capacity <= 0:\n            raise ValueError(\"capacity must be positive\")\n        self.capacity = capacity\n        self._store: \"OrderedDict[str, Any]\" = OrderedDict()\n\n    def get(self, key: str) -> Optional[Any]:\n        if key not in self._store:\n            return None\n        self._store.move_to_end(key)  # mark as most-recently-used\n        return self._store[key]\n\n    def put(self, key: str, value: Any) -> None:\n        if key in self._store:\n            self._store.move_to_end(key)\n        self._store[key] = value\n        if len(self._store) > self.capacity:\n            self._store.popitem(last=False)  # evict least-recently-used\n\n    def __contains__(self, key: str) -> bool:\n        return key in self._store\n\n    def __len__(self) -> int:\n        return len(self._store)\n\n\nif __name__ == \"__main__\":\n    cache = LRUCache(capacity=2)\n    cache.put(\"alice\", \"baseline_a\")\n    cache.put(\"bob\", \"baseline_b\")\n    cache.get(\"alice\")           # alice now most-recently-used\n    cache.put(\"carol\", \"baseline_c\")  # evicts bob (least-recently-used)\n    print(\"bob\" in cache, \"alice\" in cache, \"carol\" in cache)\n"}, {"title": "Investigation agent", "path": "Suhani_PBEL_3.0-main/source code/src/agents/investigation_agent.py", "code": "\"\"\"\nPART 3 — Agentic AI: autonomous multi-step investigation agent.\n\nEverything upstream of this module (features/, models/) produces a single\nnumber or a single sentence per user — a drift score, an anomaly flag, a\none-shot watsonx.ai explanation. This module adds an *agent*: given a\nflagged pseudonym, it plans and executes a short sequence of read-only\n\"tool calls\" against the project's own modules, accumulates the evidence\nit gathers, and — when watsonx.ai is configured — asks the model to reason\nover that accumulated evidence (not just a single row of stats) before\nproposing a next step. That plan-act-observe loop, with a visible,\nauditable trace of what it looked at and why, is what makes this \"agentic\"\nrather than just another single-shot model call like explain_drift().\n\nGuardrails (non-negotiable, matches README's \"it never acts autonomously\non a flag\"):\n  1. Every tool available to this agent is read-only. It has no access to\n     consent revocation, the QRadar export, or any other write/enforcement\n     path — those live in separate modules the agent never imports.\n  2. The agent's output is always a *recommendation* for a human analyst,\n     never an action. `requires_human_review` is hard-coded True and is\n     not something a prompt (or a compromised/hallucinating model) can\n     turn off.\n  3. Every investigation — including each intermediate tool call — is\n     written to the same tamper-evident audit log as every other scoring\n     decision in this system, so an agent run is reviewable after the\n     fact exactly like a model prediction is.\n  4. If watsonx.ai isn't configured, the agent still runs: it falls back\n     to a transparent, rule-based recommendation over the same evidence\n     it gathered, so the pipeline never silently loses this capability in\n     the free-tier/offline deployment.\n\"\"\"\nimport logging\nfrom typing import Optional\n\n\nfrom src.config import DRIFT_Z_THRESHOLD, WATSONX_ENABLED\nfrom src.data.store import read_df\nfrom src.governance.audit_log import log_event, get_recent_entries\nfrom src.governance.rag import retrieve\nfrom src.models.watsonx.client import explain_drift, _get_model\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\nAGENT_VERSION = \"agentic_investigation_v1\"\nRECENT_MESSAGES_LIMIT = 15\nPRIOR_EVENTS_SCANNED = 100\n\nACTIONS = (\"escalate_for_manual_review\", \"continue_monitoring\", \"no_action_needed\")\n\n\n# ---------------------------------------------------------------------------\n# Tools — each one is a thin, read-only wrapper around an existing module.\n# The agent's \"plan\" is the fixed order these run in below; keeping the\n# order deterministic (rather than letting an LLM freely choose which tool\n# to call, ReAct-style) means a run is reproducible and cheap to audit,\n# while the *reasoning over the results* is still delegated to watsonx.ai\n# when available. This is a deliberate, documented trade-off — same spirit\n# as rag.py choosing TF-IDF over an embedding model: inspectable over\n# maximally flexible.\n# ---------------------------------------------------------------------------\n\ndef _tool_get_risk_summary(pseudonym: str) -> Optional[dict]:\n    \"\"\"Read user risk through the project's storage abstraction.\n\n    On Vercel this resolves to Neon when DATABASE_URL is configured; during\n    local development it falls back to data/processed/user_risk.csv. Keeping\n    the agent on the same storage path as /api/users and /api/drift prevents\n    serverless requests from looking for a CSV that only exists on a laptop.\n    \"\"\"\n    df = read_df(\"user_risk\")\n    if df is None or df.empty or \"user\" not in df.columns:\n        return None\n    row = df[df[\"user\"] == pseudonym]\n    return row.iloc[0].to_dict() if not row.empty else None\n\n\ndef _tool_get_recent_messages(pseudonym: str) -> list:\n    \"\"\"Read recent scored messages through the same storage abstraction.\"\"\"\n    df = read_df(\"scored_messages\")\n    if df is None or df.empty or \"user\" not in df.columns:\n        return []\n\n    user_df = df[df[\"user\"] == pseudonym]\n    if user_df.empty:\n        return []\n\n    cols = [c for c in (\n        \"date\", \"drift_score\", \"n_flagged\", \"flagged_features\",\n        \"sentiment_polarity\", \"urgency_score\"\n    ) if c in user_df.columns]\n    return user_df[cols].tail(RECENT_MESSAGES_LIMIT).to_dict(orient=\"records\")\n\n\ndef _tool_get_prior_audit_events(pseudonym: str) -> list:\n    recent = get_recent_entries(n=PRIOR_EVENTS_SCANNED)\n    return [e for e in recent if e.get(\"user_pseudonym\") == pseudonym]\n\n\ndef _tool_search_governance_docs(query: str) -> list:\n    hits = retrieve(query, k=2)\n    return [{\"source\": h[\"source\"], \"score\": round(h[\"score\"], 3)} for h in hits]\n\n\n# ---------------------------------------------------------------------------\n# Reasoning step\n# ---------------------------------------------------------------------------\n\ndef _rule_based_recommendation(risk_summary: dict, prior_events: list) -> dict:\n    \"\"\"Transparent fallback used whenever watsonx.ai isn't configured, and\n    as the deterministic backstop if a live model call fails or returns an\n    unparseable response. Every branch is auditable from this source alone.\"\"\"\n    avg_drift = float(risk_summary.get(\"avg_drift_score\", 0) or 0)\n    flagged_rate = float(risk_summary.get(\"flagged_message_rate\", 0) or 0)\n    repeat_flags = sum(1 for e in prior_events if e.get(\"event_type\") == \"drift_flagged\")\n\n    if avg_drift >= DRIFT_Z_THRESHOLD * 1.2 or flagged_rate > 0.15 or repeat_flags >= 3:\n        return {\n            \"action\": \"escalate_for_manual_review\",\n            \"rationale\": (\n                f\"Average drift score {avg_drift:.2f} and/or flagged-message rate \"\n                f\"{flagged_rate*100:.1f}% exceed the escalation thresholds, with \"\n                f\"{repeat_flags} prior drift-flag event(s) on record for this \"\n                \"pseudonym. Rule-based fallback (watsonx.ai not consulted).\"\n            ),\n        }\n    if avg_drift >= DRIFT_Z_THRESHOLD:\n        return {\n            \"action\": \"continue_monitoring\",\n            \"rationale\": (\n                f\"Average drift score {avg_drift:.2f} is above the flagging \"\n                f\"threshold ({DRIFT_Z_THRESHOLD}) but below the escalation bar. \"\n                \"Rule-based fallback (watsonx.ai not consulted).\"\n            ),\n        }\n    return {\n        \"action\": \"no_action_needed\",\n        \"rationale\": (\n            f\"Average drift score {avg_drift:.2f} is within this user's own \"\n            \"normal range. Rule-based fallback (watsonx.ai not consulted).\"\n        ),\n    }\n\n\ndef _llm_recommendation(pseudonym: str, risk_summary: dict, messages: list,\n                         prior_events: list, explanation: Optional[str]) -> Optional[dict]:\n    \"\"\"Asks watsonx.ai to reason over *all* evidence gathered so far and\n    propose one of the fixed ACTIONS. Unlike explain_drift() (a one-shot\n    call on the summary row alone), this is the agent's synthesis step —\n    it sees the recent-message trend and the prior-audit history too.\n    Returns None (triggering the rule-based fallback) if watsonx isn't\n    configured or its response can't be parsed into a known action.\"\"\"\n    model = _get_model()\n    if model is None:\n        return None\n\n    prompt = (\n        \"You are an insider-risk investigation agent assisting a human security \"\n        \"analyst. You may only recommend one of exactly three actions — you have \"\n        \"no ability to take action yourself, only to recommend. Choose the single \"\n        \"best action and justify it in 2-3 sentences using only the evidence \"\n        \"given. Never claim certainty about intent or wrongdoing; this is a \"\n        \"statistical signal for human review only.\\n\\n\"\n        f\"Pseudonymous user: {pseudonym}\\n\"\n        f\"Risk summary: {risk_summary}\\n\"\n        f\"Recent scored messages (most recent {len(messages)}): {messages}\\n\"\n        f\"Prior audit events for this user: {len(prior_events)} on record\\n\"\n        f\"Existing plain-language explanation: {explanation or 'none available'}\\n\\n\"\n        \"Respond in EXACTLY this format:\\n\"\n        \"ACTION: <escalate_for_manual_review|continue_monitoring|no_action_needed>\\n\"\n        \"RATIONALE: <2-3 sentences>\"\n    )\n    try:\n        raw = model.generate_text(prompt=prompt)\n        text = raw.strip() if isinstance(raw, str) else str(raw)\n    except Exception as e:\n        logger.error(f\"watsonx.ai call failed during agent synthesis: {e}\")\n        return None\n\n    action = next((a for a in ACTIONS if a in text), None)\n    if action is None:\n        return None\n    rationale = text.split(\"RATIONALE:\", 1)[-1].strip() if \"RATIONALE:\" in text else text\n    return {\"action\": action, \"rationale\": rationale, \"raw_model_output\": text}\n\n\n# ---------------------------------------------------------------------------\n# Agent entry point\n# ---------------------------------------------------------------------------\n\ndef investigate_user(pseudonym: str, actor: str = \"system\") -> dict:\n    \"\"\"\n    Runs the full plan-act-observe loop for one pseudonym and returns a\n    structured, auditable investigation report. Safe to call repeatedly —\n    it never mutates risk data, consent state, or the audit chain beyond\n    appending its own trace entries.\n    \"\"\"\n    trace = []\n\n    risk_summary = _tool_get_risk_summary(pseudonym)\n    trace.append({\"tool\": \"get_risk_summary\", \"found\": risk_summary is not None})\n    if risk_summary is None:\n        return {\n            \"user_pseudonym\": pseudonym,\n            \"generated_by\": AGENT_VERSION,\n            \"error\": f\"No risk data for pseudonym '{pseudonym}'. Has the pipeline been run?\",\n            \"evidence_trace\": trace,\n            \"requires_human_review\": True,\n        }\n\n    messages = _tool_get_recent_messages(pseudonym)\n    trace.append({\"tool\": \"get_recent_messages\", \"count\": len(messages)})\n\n    prior_events = _tool_get_prior_audit_events(pseudonym)\n    trace.append({\"tool\": \"get_prior_audit_events\", \"count\": len(prior_events)})\n\n    explanation = explain_drift(pseudonym, risk_summary)\n    trace.append({\"tool\": \"get_watsonx_explanation\", \"available\": explanation is not None})\n\n    # Only spend a retrieval + reasoning step on governance docs when the\n    # evidence so far is actually borderline enough to warrant it — keeps\n    # low-risk users cheap to investigate.\n    policy_context = []\n    avg_drift = float(risk_summary.get(\"avg_drift_score\", 0) or 0)\n    if avg_drift >= DRIFT_Z_THRESHOLD:\n        policy_context = _tool_search_governance_docs(\n            \"insider risk escalation review consent audit process\"\n        )\n        trace.append({\"tool\": \"search_governance_docs\", \"hits\": len(policy_context)})\n\n    recommendation = _llm_recommendation(pseudonym, risk_summary, messages, prior_events, explanation)\n    used_llm = recommendation is not None\n    if recommendation is None:\n        recommendation = _rule_based_recommendation(risk_summary, prior_events)\n    trace.append({\"tool\": \"synthesize_recommendation\", \"used_watsonx\": used_llm})\n\n    report = {\n        \"user_pseudonym\": pseudonym,\n        \"generated_by\": AGENT_VERSION,\n        \"watsonx_reasoning_used\": used_llm,\n        \"watsonx_configured\": WATSONX_ENABLED,\n        \"risk_summary\": risk_summary,\n        \"explanation\": explanation,\n        \"policy_context\": policy_context,\n        \"recommendation\": recommendation[\"action\"],\n        \"rationale\": recommendation[\"rationale\"],\n        \"evidence_trace\": trace,\n        # Hard-coded, not model-controllable: the agent proposes, a human\n        # analyst/admin disposes. See module docstring guardrail (2).\n        \"requires_human_review\": True,\n    }\n\n    log_event(\n        \"agent_investigation_completed\",\n        pseudonym,\n        {\n            \"recommendation\": recommendation[\"action\"],\n            \"watsonx_reasoning_used\": used_llm,\n            \"steps\": len(trace),\n        },\n        actor=actor,\n    )\n    return report\n\n\nif __name__ == \"__main__\":\n    import json\n    import sys\n    target = sys.argv[1] if len(sys.argv) > 1 else \"emp_abc123\"\n    print(json.dumps(investigate_user(target), indent=2, default=str))"}, {"title": "Audit log", "path": "Suhani_PBEL_3.0-main/source code/src/governance/audit_log.py", "code": "\"\"\"\nPART 2 — Audit logging (watsonx.governance-style).\n\nEvery scoring decision, drift flag, and watsonx.ai call that touches a\nreal (pseudonymized) user should leave an append-only, tamper-evident\ntrail — this is the \"responsibly audit/limit this\" requirement from the\nmentor's notes made concrete.\n\nDesign: JSON Lines file, each entry hash-chained to the previous one\n(entry.prev_hash = hash of previous entry), so any retroactive edit or\ndeletion breaks the chain and is detectable by verify_chain(). This is\nthe same core idea as a blockchain's tamper-evidence, applied to a single\nappend-only log rather than a distributed ledger — appropriate here since\nwe don't need consensus, just detectability.\n\nIn a real IBM Cloud deployment this would write to a governed store\n(e.g. watsonx.governance's own audit trail, or an immutable Cloud Object\nStorage bucket with retention lock) instead of a local file — swap\n_append() to do that without touching call sites.\n\"\"\"\nimport json\nimport hashlib\nimport logging\nimport os\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Optional\n\nfrom src.config import AUDIT_LOG_PATH\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n\ndef _resolve_writable_log_path(preferred: Path) -> Path:\n    \"\"\"\n    Serverless deploy targets (Vercel's Python runtime among them) ship the\n    function bundle as a read-only filesystem — only /tmp is writable, and\n    /tmp is ephemeral per invocation/container. `preferred` (the real\n    ROOT_DIR-relative path, fine for local dev / a real container deploy\n    like IBM Code Engine) is used when its parent directory is actually\n    writable; otherwise we fall back to /tmp so log_event() below can\n    always succeed rather than throwing OSError/PermissionError straight\n    through every route that calls it (that was crashing\n    /api/drift/messages and /api/drift/explain with 500s on Vercel,\n    unrelated to watsonx).\n    \"\"\"\n    try:\n        preferred.parent.mkdir(parents=True, exist_ok=True)\n        probe = preferred.parent / \".write_test\"\n        with open(probe, \"w\") as f:\n            f.write(\"ok\")\n        probe.unlink(missing_ok=True)\n        return preferred\n    except OSError:\n        fallback = Path(\"/tmp\") / preferred.name\n        logger.warning(\n            f\"Audit log path {preferred} is not writable in this environment \"\n            f\"(read-only filesystem, e.g. Vercel serverless) — falling back to \"\n            f\"{fallback}. Note: /tmp is ephemeral, so this fallback log does not \"\n            f\"persist across deployments/cold starts. For a durable audit trail \"\n            f\"in serverless, point AUDIT_LOG_PATH at external storage instead.\"\n        )\n        return fallback\n\n\nAUDIT_LOG_PATH = _resolve_writable_log_path(AUDIT_LOG_PATH)\n\n\ndef _hash_entry(entry: dict) -> str:\n    payload = json.dumps(entry, sort_keys=True, default=str).encode(\"utf-8\")\n    return hashlib.sha256(payload).hexdigest()\n\n\ndef _last_hash() -> str:\n    if not AUDIT_LOG_PATH.exists() or AUDIT_LOG_PATH.stat().st_size == 0:\n        return \"0\" * 64  # genesis\n    with open(AUDIT_LOG_PATH, \"rb\") as f:\n        last_line = None\n        for line in f:\n            if line.strip():\n                last_line = line\n    if last_line is None:\n        return \"0\" * 64\n    return json.loads(last_line)[\"entry_hash\"]\n\n\ndef log_event(event_type: str, user_pseudonym: Optional[str], details: dict,\n              actor: str = \"system\") -> dict:\n    \"\"\"\n    event_type examples: 'drift_flagged', 'watsonx_explanation_generated',\n    'model_prediction', 'consent_revoked', 'api_access'\n    \"\"\"\n    entry = {\n        \"timestamp\": datetime.now(timezone.utc).isoformat(),\n        \"event_type\": event_type,\n        \"user_pseudonym\": user_pseudonym,  # NEVER a real username — pseudonyms only\n        \"actor\": actor,\n        \"details\": details,\n        \"prev_hash\": _last_hash(),\n    }\n    entry[\"entry_hash\"] = _hash_entry(entry)\n\n    try:\n        with open(AUDIT_LOG_PATH, \"a\") as f:\n            f.write(json.dumps(entry, default=str) + \"\\n\")\n    except OSError as e:\n        # Audit logging is important but must never be able to take down the\n        # feature it's logging (drift lookup, explanation, etc.) — a route\n        # returning data to an analyst shouldn't 500 just because the append\n        # failed. Log loudly server-side instead so the gap is visible.\n        logger.error(f\"Failed to write audit log entry ({event_type}): {e}\")\n\n    return entry\n\n\ndef verify_chain() -> bool:\n    \"\"\"Walk the whole log and confirm each entry's prev_hash matches the prior entry's hash.\"\"\"\n    if not AUDIT_LOG_PATH.exists():\n        return True\n\n    expected_prev = \"0\" * 64\n    with open(AUDIT_LOG_PATH, \"r\") as f:\n        for i, line in enumerate(f):\n            if not line.strip():\n                continue\n            entry = json.loads(line)\n            if entry[\"prev_hash\"] != expected_prev:\n                logger.error(f\"Audit chain broken at line {i}: prev_hash mismatch.\")\n                return False\n            claimed_hash = entry.pop(\"entry_hash\")\n            recomputed = _hash_entry(entry)\n            if claimed_hash != recomputed:\n                logger.error(f\"Audit chain broken at line {i}: entry_hash mismatch (tampered content).\")\n                return False\n            expected_prev = claimed_hash\n    logger.info(\"Audit chain verified OK.\")\n    return True\n\n\ndef get_recent_entries(n: int = 20) -> list:\n    \"\"\"\n    Return the most recent `n` log entries (oldest to newest), each with its\n    'entry_hash'/'prev_hash' bookkeeping fields intact. Used by `signal audit\n    tail` (src/api CLI) and by src/governance/rag.py, which folds recent\n    entries into its retrieval corpus so an analyst can ask natural-language\n    questions like \"was anything unusual logged recently?\" and get an answer\n    grounded in the real audit trail, not just the static docs.\n    \"\"\"\n    if not AUDIT_LOG_PATH.exists():\n        return []\n    with open(AUDIT_LOG_PATH, \"r\") as f:\n        lines = [line for line in f if line.strip()]\n    return [json.loads(line) for line in lines[-n:]]\n\n\nif __name__ == \"__main__\":\n    log_event(\"drift_flagged\", \"emp_abc123\", {\"drift_score\": 3.2, \"flagged_features\": [\"urgency_score\"]})\n    log_event(\"model_prediction\", \"emp_abc123\", {\"model\": \"random_forest\", \"risk_proba\": 0.81})\n    print(\"Chain valid:\", verify_chain())\n    print(\"Recent entries:\", get_recent_entries(n=5))\n"}, {"title": "Consent gate", "path": "Suhani_PBEL_3.0-main/source code/src/governance/consent.py", "code": "\"\"\"\nPART 1 — Consent gating.\n\nThis is the \"privacy-by-design\" piece the mentor's notes flagged as the\ndifferentiator: linguistic drift analysis on employee communications is\nsensitive, so nothing downstream (features, baselines, drift scoring)\nshould run for a user without a recorded, current consent record.\n\nDesign: a simple CSV-backed consent ledger (data/interim/consent.csv) with\ncolumns [user, consented, consented_on, scope]. In production this would\nbe backed by an actual HR/legal system of record — this module just\ndefines the *interface* the rest of the pipeline depends on, so swapping\nthe backing store later doesn't touch feature/model code.\n\"\"\"\nimport logging\nfrom pathlib import Path\nfrom typing import Set\n\nimport pandas as pd\n\nfrom src.config import DATA_INTERIM, CONSENT_REQUIRED\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\nCONSENT_PATH = DATA_INTERIM / \"consent.csv\"\n\n\ndef ensure_consent_ledger(all_users: Set[str]) -> None:\n    \"\"\"\n    Create a default consent ledger if one doesn't exist yet. Defaults\n    everyone to consented=True ONLY for local dev/demo purposes — in a\n    real deployment this file must come from an actual consent system,\n    never be auto-generated as \"opt-in by default.\"\n    \"\"\"\n    if CONSENT_PATH.exists():\n        return\n    logger.warning(\n        \"No consent.csv found — generating a DEV-ONLY default ledger with \"\n        \"all users opted in. Replace this with a real consent system of \"\n        \"record before using on real employee data.\"\n    )\n    df = pd.DataFrame({\n        \"user\": sorted(all_users),\n        \"consented\": True,\n        \"consented_on\": pd.Timestamp.now().strftime(\"%Y-%m-%d\"),\n        \"scope\": \"linguistic_drift_analysis_v1\",\n    })\n    df.to_csv(CONSENT_PATH, index=False)\n\n\ndef get_consented_users() -> Set[str]:\n    if not CONSENT_REQUIRED:\n        return set()  # sentinel: caller should treat \"consent not required\" specially\n    if not CONSENT_PATH.exists():\n        return set()\n    df = pd.read_csv(CONSENT_PATH)\n    return set(df.loc[df[\"consented\"] == True, \"user\"])  # noqa: E712\n\n\ndef filter_to_consented(df: pd.DataFrame, user_col: str = \"user\") -> pd.DataFrame:\n    \"\"\"Drop rows for any user without an active consent record. No-op if CONSENT_REQUIRED=False.\"\"\"\n    if not CONSENT_REQUIRED:\n        return df\n\n    ensure_consent_ledger(set(df[user_col].unique()))\n    consented = get_consented_users()\n    before = len(df)\n    filtered = df[df[user_col].isin(consented)].copy()\n    dropped = before - len(filtered)\n    if dropped:\n        logger.info(f\"Consent gate: dropped {dropped}/{before} rows for non-consented users.\")\n    return filtered\n\n\ndef revoke_consent(user: str) -> None:\n    \"\"\"Mark a user as no longer consented. Downstream jobs should re-check before their next run.\"\"\"\n    if not CONSENT_PATH.exists():\n        return\n    df = pd.read_csv(CONSENT_PATH)\n    df.loc[df[\"user\"] == user, \"consented\"] = False\n    df.to_csv(CONSENT_PATH, index=False)\n    logger.info(f\"Consent revoked for user={user}\")\n"}, {"title": "CI-oriented pipeline test", "path": "Suhani_PBEL_3.0-main/source code/tests/test_core.py", "code": "\"\"\"\nBasic tests covering the DSA structures and core scoring logic. Run with:\n    pytest tests/\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\n\nfrom src.dsa.sliding_window import SlidingWindowStats\nfrom src.dsa.trie_phrase_matcher import AhoCorasick\nfrom src.dsa.top_k_heap import TopKRiskHeap\nfrom src.dsa.lru_cache_baselines import LRUCache\nfrom src.features.drift_scoring import score_drift\nfrom src.data.anonymize import pseudonymize_user\n\n\nclass TestSlidingWindowStats:\n    def test_mean_and_std(self):\n        w = SlidingWindowStats(window_size=3)\n        for v in [2, 4, 6]:\n            w.push(v)\n        assert w.mean == 4.0\n        assert w.count == 3\n\n    def test_eviction(self):\n        w = SlidingWindowStats(window_size=2)\n        w.push(1)\n        w.push(2)\n        w.push(3)  # should evict the 1\n        assert w.count == 2\n        assert w.mean == 2.5\n\n    def test_zero_variance_zscore_is_zero(self):\n        w = SlidingWindowStats(window_size=3)\n        for _ in range(3):\n            w.push(5.0)\n        assert w.z_score(5.0) == 0.0\n\n    def test_z_score_direction(self):\n        w = SlidingWindowStats(window_size=5)\n        for v in [1, 2, 3, 4, 5]:\n            w.push(v)\n        assert w.z_score(100) > 0\n        assert w.z_score(-100) < 0\n\n\nclass TestAhoCorasick:\n    def test_finds_known_phrase(self):\n        ac = AhoCorasick([\"urgent\", \"wire transfer\"])\n        matches = ac.scan(\"this is urgent, please wire transfer now\")\n        found_phrases = {m[0] for m in matches}\n        assert \"urgent\" in found_phrases\n        assert \"wire transfer\" in found_phrases\n\n    def test_no_match_returns_empty(self):\n        ac = AhoCorasick([\"urgent\"])\n        assert ac.scan(\"hope you have a great weekend\") == []\n\n    def test_urgency_score_bounded(self):\n        ac = AhoCorasick([\"urgent\", \"asap\", \"wire transfer\"])\n        score = ac.urgency_score(\"urgent asap wire transfer urgent asap\")\n        assert 0.0 <= score <= 1.0\n\n\nclass TestTopKRiskHeap:\n    def test_keeps_only_top_k(self):\n        heap = TopKRiskHeap(k=2)\n        for uid, score in [(\"a\", 0.1), (\"b\", 0.9), (\"c\", 0.5)]:\n            heap.push(uid, score)\n        top = heap.top_k()\n        assert len(top) == 2\n        assert top[0].user_id == \"b\"\n        assert top[1].user_id == \"c\"\n\n    def test_sorted_descending(self):\n        heap = TopKRiskHeap(k=5)\n        for uid, score in [(\"a\", 0.3), (\"b\", 0.9), (\"c\", 0.1)]:\n            heap.push(uid, score)\n        scores = [e.score for e in heap.top_k()]\n        assert scores == sorted(scores, reverse=True)\n\n\nclass TestLRUCache:\n    def test_basic_get_put(self):\n        cache = LRUCache(capacity=2)\n        cache.put(\"a\", 1)\n        assert cache.get(\"a\") == 1\n\n    def test_eviction_order(self):\n        cache = LRUCache(capacity=2)\n        cache.put(\"a\", 1)\n        cache.put(\"b\", 2)\n        cache.get(\"a\")       # a is now most-recently-used\n        cache.put(\"c\", 3)    # should evict b\n        assert \"b\" not in cache\n        assert \"a\" in cache\n        assert \"c\" in cache\n\n\nclass TestDriftScoring:\n    def test_no_drift_when_no_zscores(self):\n        result = score_drift({})\n        assert result[\"drift_score\"] == 0.0\n        assert result[\"flagged_features\"] == []\n\n    def test_flags_above_threshold(self):\n        result = score_drift({\"z_urgency_score\": 5.0, \"z_sentiment_polarity\": 0.1})\n        assert \"urgency_score\" in result[\"flagged_features\"]\n        assert \"sentiment_polarity\" not in result[\"flagged_features\"]\n\n    def test_extreme_zscore_is_clipped(self):\n        # a near-zero-variance feature shouldn't be able to blow up the score unboundedly\n        result = score_drift({\"z_urgency_score\": 100000.0})\n        assert result[\"drift_score\"] <= 10.0 + 1e-6\n\n\nclass TestAnonymize:\n    def test_deterministic(self):\n        assert pseudonymize_user(\"alice\") == pseudonymize_user(\"alice\")\n\n    def test_different_users_differ(self):\n        assert pseudonymize_user(\"alice\") != pseudonymize_user(\"bob\")\n\n    def test_format(self):\n        assert pseudonymize_user(\"alice\").startswith(\"emp_\")\n"}], "sentinel": [{"title": "Rate-limit filter", "path": "sentinel-rate-main/rate-limiter-service/rate-limiter/src/main/java/com/sentinel/ratelimiter/filter/RateLimitFilter.java", "code": "package com.sentinel.ratelimiter.filter;\n\nimport tools.jackson.databind.ObjectMapper;\nimport com.sentinel.ratelimiter.config.RateLimitDefaults;\nimport com.sentinel.ratelimiter.dto.RateLimitResponse;\nimport com.sentinel.ratelimiter.metrics.RateLimitMetrics;\nimport com.sentinel.ratelimiter.service.AbuseDetectionService;\nimport com.sentinel.ratelimiter.service.EventPersistenceService;\nimport com.sentinel.ratelimiter.service.RateLimiterService;\nimport com.sentinel.ratelimiter.service.RateLimiterService.RateLimitDecision;\nimport jakarta.servlet.FilterChain;\nimport jakarta.servlet.ServletException;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.stereotype.Component;\nimport org.springframework.web.filter.OncePerRequestFilter;\n\nimport java.io.IOException;\n\n@Component\npublic class RateLimitFilter extends OncePerRequestFilter {\n\n    private static final String HEADER_LIMIT = \"X-RateLimit-Limit\";\n    private static final String HEADER_REM = \"X-RateLimit-Remaining\";\n    private static final String HEADER_RESET = \"X-RateLimit-Reset\";\n    private static final String HEADER_RETRY = \"Retry-After\";\n\n    private final RateLimiterService rateLimiterService;\n    private final AbuseDetectionService abuseDetectionService;\n    private final EventPersistenceService persistenceService;\n    private final RateLimitMetrics metrics;\n    private final ObjectMapper objectMapper;\n\n    public RateLimitFilter(RateLimiterService rateLimiterService,\n                           AbuseDetectionService abuseDetectionService,\n                           EventPersistenceService persistenceService,\n                           RateLimitMetrics metrics,\n                           ObjectMapper objectMapper) {\n\n        this.rateLimiterService = rateLimiterService;\n        this.abuseDetectionService = abuseDetectionService;\n        this.persistenceService = persistenceService;\n        this.metrics = metrics;\n        this.objectMapper = objectMapper;\n    }\n\n    @Override\n    protected void doFilterInternal(HttpServletRequest request,\n                                    HttpServletResponse response,\n                                    FilterChain filterChain)\n            throws ServletException, IOException {\n\n        String clientId = resolveClientId(request);\n\n        // Check if client is blocked\n        if (abuseDetectionService.isBlocked(clientId)) {\n\n            metrics.recordBlocked();\n\n            persistenceService.saveRateLimitEvent(clientId, false, 0);\n\n            rejectWith(\n                    response,\n                    HttpStatus.FORBIDDEN,\n                    new RateLimitResponse(false, 0,\n                            \"Client blocked due to repeated abuse\")\n            );\n\n            return;\n        }\n\n        RateLimitDecision decision = rateLimiterService.isAllowed(clientId);\n\n        long resetEpoch =\n                (System.currentTimeMillis() / 1000) + RateLimitDefaults.DEFAULT_WINDOW_SECONDS;\n\n        response.setIntHeader(HEADER_LIMIT, RateLimitDefaults.DEFAULT_MAX_REQUESTS);\n        response.setIntHeader(HEADER_REM, decision.remaining());\n        response.setHeader(HEADER_RESET, String.valueOf(resetEpoch));\n\n        persistenceService.saveRateLimitEvent(\n                clientId,\n                decision.allowed(),\n                decision.remaining()\n        );\n\n        // Block request if limit exceeded\n        if (!decision.allowed()) {\n\n            metrics.recordBlocked();\n\n            abuseDetectionService.recordViolation(clientId);\n\n            response.setIntHeader(HEADER_RETRY, RateLimitDefaults.DEFAULT_WINDOW_SECONDS);\n\n            rejectWith(\n                    response,\n                    HttpStatus.TOO_MANY_REQUESTS,\n                    new RateLimitResponse(false, 0,\n                            \"Rate limit exceeded\")\n            );\n\n            return;\n        }\n\n        // Allowed request\n        metrics.recordAllowed();\n\n        filterChain.doFilter(request, response);\n    }\n\n    private String resolveClientId(HttpServletRequest request) {\n\n        String xff = request.getHeader(\"X-Forwarded-For\");\n\n        if (xff != null && !xff.isBlank()) {\n            return xff.split(\",\")[0].trim();\n        }\n\n        return request.getRemoteAddr();\n    }\n\n    private void rejectWith(HttpServletResponse response,\n                            HttpStatus status,\n                            RateLimitResponse body)\n            throws IOException {\n\n        response.setStatus(status.value());\n        response.setContentType(MediaType.APPLICATION_JSON_VALUE);\n\n        objectMapper.writeValue(response.getWriter(), body);\n    }\n}\n"}, {"title": "Rate limiter service", "path": "sentinel-rate-main/rate-limiter-service/rate-limiter/src/main/java/com/sentinel/ratelimiter/service/RateLimiterService.java", "code": "package com.sentinel.ratelimiter.service;\n\nimport com.sentinel.ratelimiter.config.RateLimitDefaults;\nimport org.springframework.data.redis.core.StringRedisTemplate;\nimport org.springframework.data.redis.core.script.RedisScript;\nimport org.springframework.stereotype.Service;\n\nimport java.time.Duration;\nimport java.util.Collections;\nimport java.util.List;\n\n/**\n * Sliding-window rate limiter backed by a Redis sorted set + Lua script.\n *\n * <p>Uses a single atomic Lua script so that the ZREMRANGEBYSCORE → ZADD → ZCARD\n * sequence is never split across two requests, eliminating the race condition\n * present in the previous counter-increment approach.\n *\n * <p>Key schema: {@code rate_limit:<clientId>}\n *   - Sorted set where score = epoch-millis of each request timestamp\n *   - Entries older than the window are pruned on every call (O(log n + k))\n */\n@Service\npublic class RateLimiterService {\n\n    private final StringRedisTemplate redisTemplate;\n\n    /**\n     * Atomic sliding-window script.\n     *\n     * KEYS[1] = rate_limit:<clientId>\n     * ARGV[1] = current epoch-millis (string)\n     * ARGV[2] = window start epoch-millis (current - window)\n     * ARGV[3] = max requests\n     * ARGV[4] = window size in ms  (used as TTL for the sorted set)\n     *\n     * Returns: {allowed (0|1), current_count}\n     */\n    private static final String SLIDING_WINDOW_SCRIPT = \"\"\"\n            local key       = KEYS[1]\n            local now       = tonumber(ARGV[1])\n            local win_start = tonumber(ARGV[2])\n            local limit     = tonumber(ARGV[3])\n            local win_ms    = tonumber(ARGV[4])\n\n            -- 1. Evict timestamps outside the window\n            redis.call('ZREMRANGEBYSCORE', key, 0, win_start)\n\n            -- 2. Count remaining\n            local count = redis.call('ZCARD', key)\n\n            if count < limit then\n                -- 3. Record this request (score = timestamp, member = timestamp for uniqueness)\n                redis.call('ZADD', key, now, now .. '-' .. math.random(1, 1000000))\n                -- 4. Reset TTL so the key expires naturally after the window\n                redis.call('PEXPIRE', key, win_ms)\n                return {1, count + 1}\n            else\n                return {0, count}\n            end\n            \"\"\";\n\n    private final RedisScript<List<Long>> script;\n\n    public RateLimiterService(StringRedisTemplate redisTemplate) {\n        this.redisTemplate = redisTemplate;\n        this.script = RedisScript.of(SLIDING_WINDOW_SCRIPT, (Class<List<Long>>) (Class<?>) List.class);\n    }\n\n    /**\n     * Checks whether {@code clientId} is within the default rate limit\n     * ({@link RateLimitDefaults#DEFAULT_MAX_REQUESTS} requests per\n     * {@link RateLimitDefaults#DEFAULT_WINDOW_SECONDS}s window).\n     *\n     * @param clientId opaque client identifier (IP, API-key, user-id, …)\n     * @return {@link RateLimitDecision} containing allowed flag and current count\n     */\n    public RateLimitDecision isAllowed(String clientId) {\n        return isAllowed(clientId, RateLimitDefaults.DEFAULT_MAX_REQUESTS, RateLimitDefaults.DEFAULT_WINDOW_SECONDS);\n    }\n\n    /**\n     * Checks whether {@code clientId} is within a caller-supplied rate limit. This is what\n     * powers per-endpoint overrides: {@link com.sentinel.ratelimiter.aspect.RateLimitAspect}\n     * calls this directly with the values from a method's {@code @RateLimit} annotation,\n     * while {@link com.sentinel.ratelimiter.filter.RateLimitFilter} calls the single-arg\n     * {@link #isAllowed(String)} overload for the global default.\n     *\n     * @param clientId      opaque client identifier (IP, API-key, user-id, …)\n     * @param maxRequests   maximum requests allowed inside the rolling window\n     * @param windowSeconds rolling window size, in seconds\n     * @return {@link RateLimitDecision} containing allowed flag and current count\n     */\n    public RateLimitDecision isAllowed(String clientId, int maxRequests, int windowSeconds) {\n        long windowMs = Duration.ofSeconds(windowSeconds).toMillis();\n        long now      = System.currentTimeMillis();\n        long winStart = now - windowMs;\n\n        List<Long> result = redisTemplate.execute(\n                script,\n                Collections.singletonList(\"rate_limit:\" + clientId),\n                String.valueOf(now),\n                String.valueOf(winStart),\n                String.valueOf(maxRequests),\n                String.valueOf(windowMs)\n        );\n\n        boolean allowed = result != null && result.get(0) == 1L;\n        long    count   = result != null ? result.get(1) : maxRequests;\n\n        return new RateLimitDecision(allowed, (int) Math.max(0, maxRequests - count));\n    }\n\n    /** Value object returned to callers so they can populate response headers. */\n    public record RateLimitDecision(boolean allowed, int remaining) {}\n}\n"}, {"title": "LangGraph agent graph", "path": "sentinel-rate-main/agent-service/app/graph.py", "code": "\"\"\"Agentic abuse-investigation workflow, built with LangGraph.\n\nGraph shape:\n\n    gather_context --> assess_risk --> policy_decision --(high risk)--> escalate --> END\n                                              \\\\--(low/medium risk)--> auto_resolve --> END\n\nEach request to the rate-limiter's abuse pipeline can be routed through this\ngraph to get an explainable, multi-step recommendation instead of a single\nopaque model call: we gather derived signal, get a risk assessment (LLM or\noffline heuristic), then apply a deterministic policy layer on top before\ndeciding whether the case needs a human, rather than trusting the model\noutput blindly.\n\"\"\"\nfrom typing import List, TypedDict\n\nfrom langgraph.graph import StateGraph, END\n\nfrom .llm import assess_with_llm, assess_heuristically, parse_assessment, llm_is_configured\nfrom .models import RateLimitEvent\n\n\nclass AgentState(TypedDict, total=False):\n    client_id: str\n    violation_count: int\n    endpoint: str\n    window_seconds: int\n    recent_events: List[RateLimitEvent]\n    blocked_ratio: float\n    risk_score: float\n    risk_level: str\n    recommended_action: str\n    requires_human_review: bool\n    reasoning: str\n    used_llm: bool\n\n\ndef gather_context(state: AgentState) -> AgentState:\n    events = state.get(\"recent_events\", [])\n    blocked = sum(1 for e in events if not e.allowed)\n    state[\"blocked_ratio\"] = (blocked / len(events)) if events else 0.0\n    return state\n\n\ndef assess_risk(state: AgentState) -> AgentState:\n    prompt = (\n        \"You are an abuse-detection analyst for a rate-limiting service. \"\n        f\"Client '{state['client_id']}' has {state['violation_count']} rate-limit \"\n        f\"violations in the last {state['window_seconds']}s on endpoint \"\n        f\"'{state['endpoint']}', with a blocked-request ratio of \"\n        f\"{state['blocked_ratio']:.2f}. Respond ONLY in this exact format:\\n\"\n        \"risk_score: <0.0-1.0>\\nrisk_level: <low|medium|high>\\n\"\n        \"recommended_action: <allow|monitor|extend_block>\\nreasoning: <one sentence>\"\n    )\n\n    used_llm = False\n    if llm_is_configured():\n        try:\n            raw = assess_with_llm(prompt)\n            used_llm = True\n        except Exception:\n            raw = assess_heuristically(state[\"violation_count\"], state.get(\"recent_events\", []))\n    else:\n        raw = assess_heuristically(state[\"violation_count\"], state.get(\"recent_events\", []))\n\n    parsed = parse_assessment(raw)\n    state[\"risk_score\"] = parsed[\"risk_score\"]\n    state[\"risk_level\"] = parsed[\"risk_level\"]\n    state[\"recommended_action\"] = parsed[\"recommended_action\"]\n    state[\"reasoning\"] = parsed[\"reasoning\"]\n    state[\"used_llm\"] = used_llm\n    return state\n\n\ndef policy_decision(state: AgentState) -> AgentState:\n    # Deterministic guardrail layered on top of the model's opinion: a\n    # client with 10+ violations is always escalated, regardless of what\n    # the assessment step returned.\n    if state[\"violation_count\"] >= 10 or state[\"risk_score\"] >= 0.7:\n        state[\"requires_human_review\"] = True\n    else:\n        state[\"requires_human_review\"] = False\n    return state\n\n\ndef route_after_policy(state: AgentState) -> str:\n    return \"escalate\" if state[\"requires_human_review\"] else \"auto_resolve\"\n\n\ndef escalate(state: AgentState) -> AgentState:\n    state[\"recommended_action\"] = \"extend_block\"\n    return state\n\n\ndef auto_resolve(state: AgentState) -> AgentState:\n    return state\n\n\ndef build_graph():\n    graph = StateGraph(AgentState)\n    graph.add_node(\"gather_context\", gather_context)\n    graph.add_node(\"assess_risk\", assess_risk)\n    graph.add_node(\"policy_decision\", policy_decision)\n    graph.add_node(\"escalate\", escalate)\n    graph.add_node(\"auto_resolve\", auto_resolve)\n\n    graph.set_entry_point(\"gather_context\")\n    graph.add_edge(\"gather_context\", \"assess_risk\")\n    graph.add_edge(\"assess_risk\", \"policy_decision\")\n    graph.add_conditional_edges(\n        \"policy_decision\",\n        route_after_policy,\n        {\"escalate\": \"escalate\", \"auto_resolve\": \"auto_resolve\"},\n    )\n    graph.add_edge(\"escalate\", END)\n    graph.add_edge(\"auto_resolve\", END)\n    return graph.compile()\n\n\n_compiled_graph = None\n\n\ndef get_graph():\n    global _compiled_graph\n    if _compiled_graph is None:\n        _compiled_graph = build_graph()\n    return _compiled_graph\n"}, {"title": "GitHub Actions CI", "path": "sentinel-rate-main/.github/workflows/ci.yml", "code": "name: CI\n\non:\n  push:\n    branches: [main, develop]\n  pull_request:\n    branches: [main]\n\njobs:\n  build-and-test:\n    runs-on: ubuntu-latest\n\n    services:\n      redis:\n        image: redis:7-alpine\n        ports:\n          - 6379:6379\n        options: >-\n          --health-cmd \"redis-cli ping\"\n          --health-interval 5s\n          --health-timeout 3s\n          --health-retries 5\n\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Set up JDK 17\n        uses: actions/setup-java@v4\n        with:\n          java-version: '17'\n          distribution: 'temurin'\n          cache: maven\n\n      # jacoco-maven-plugin's \"check\" goal is bound to the verify phase in pom.xml, so this\n      # step fails outright if line coverage drops below jacoco.line.coverage.minimum. The\n      # old separate \"enforce coverage\" step here used to just grep-and-echo a raw\n      # instruction count with a `|| echo \"0\"` fallback — it never actually failed the build.\n      - name: Build & run tests (enforces JaCoCo coverage gate)\n        working-directory: rate-limiter-service/rate-limiter\n        run: ./mvnw verify -B\n\n      - name: Upload JaCoCo report\n        if: always()\n        uses: actions/upload-artifact@v4\n        with:\n          name: jacoco-report\n          path: rate-limiter-service/rate-limiter/target/site/jacoco/\n\n  agent-service:\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Set up Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: '3.12'\n          cache: pip\n          cache-dependency-path: agent-service/requirements.txt\n\n      - name: Install dependencies\n        working-directory: agent-service\n        run: pip install -r requirements.txt\n\n      # No ANTHROPIC_API_KEY is set here on purpose: the agent must fall\n      # back to its offline heuristic so the LangGraph workflow is fully\n      # testable without secrets or network access to an LLM provider.\n      - name: Run tests\n        working-directory: agent-service\n        run: pytest -q\n\n      - name: Build agent Docker image\n        run: docker build -t sentinel-agent:ci agent-service\n\n  docker-smoke:\n    runs-on: ubuntu-latest\n    needs: build-and-test\n\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Build Docker image\n        run: docker build -t sentinel-rate:ci .\n\n      - name: Smoke-test container\n        run: |\n          docker network create sentinel-net\n          docker run -d --name sentinel-redis --network sentinel-net redis:7-alpine\n          docker run -d --name sentinel-app \\\n            --network sentinel-net \\\n            -e SPRING_DATA_REDIS_HOST=sentinel-redis \\\n            -e SPRING_DATA_REDIS_PORT=6379 \\\n            -p 8080:8080 sentinel-rate:ci\n\n          echo \"Waiting for the app to become healthy...\"\n          for i in $(seq 1 30); do\n            STATUS=$(curl -s -o /dev/null -w \"%{http_code}\" http://localhost:8080/health || echo \"000\")\n            if [ \"$STATUS\" = \"200\" ]; then\n              echo \"Health check returned HTTP $STATUS after $((i * 2))s\"\n              exit 0\n            fi\n            sleep 2\n          done\n\n          echo \"App never became healthy within 60s — dumping container logs:\"\n          docker logs sentinel-app\n          exit 1\n\n      - name: Cleanup containers\n        if: always()\n        run: |\n          docker rm -f sentinel-app sentinel-redis || true\n          docker network rm sentinel-net || true\n"}], "multi": [{"title": "App factory & config", "path": "multi-vendor-e-commerce-main/backend/app/__init__.py", "code": "from datetime import datetime\n\nfrom flask import Flask\n\nfrom app.config import get_config\nfrom app.extensions import cors, db, jwt, migrate\n\n\ndef create_app(config_name: str | None = None) -> Flask:\n    app = Flask(__name__)\n    app.config.from_object(get_config(config_name))\n\n    db.init_app(app)\n    migrate.init_app(app, db)\n    jwt.init_app(app)\n    cors.init_app(app, resources={r\"/api/*\": {\"origins\": \"*\"}})\n\n    _register_blueprints(app)\n    _register_cli(app)\n\n    @app.get(\"/api/health\")\n    def health():\n        return {\"status\": \"ok\"}\n\n    return app\n\n\ndef _register_cli(app: Flask) -> None:\n    import os\n\n    @app.cli.command(\"seed-admin\")\n    def seed_admin():\n        \"\"\"Create the admin user from ADMIN_EMAIL/ADMIN_PASSWORD env vars.\n\n        Safe to run on every deploy — does nothing if the user already\n        exists. This is how a first login gets created on hosts (e.g.\n        Render's free tier) where a shell isn't available.\n        \"\"\"\n        from werkzeug.security import generate_password_hash\n\n        from app.extensions import db\n        from app.models import User, UserRole\n\n        email = os.environ.get(\"ADMIN_EMAIL\")\n        password = os.environ.get(\"ADMIN_PASSWORD\")\n\n        if not email or not password:\n            print(\"ADMIN_EMAIL / ADMIN_PASSWORD not set — skipping admin seed.\")\n            return\n\n        if User.query.filter_by(email=email).first():\n            print(f\"Admin user {email} already exists — skipping.\")\n            return\n\n        admin = User(\n            email=email,\n            password_hash=generate_password_hash(password),\n            role=UserRole.ADMIN,\n        )\n        db.session.add(admin)\n        db.session.commit()\n        print(f\"Created admin user {email}.\")\n\n    @app.cli.command(\"seed-demo-data\")\n    def seed_demo_data():\n        \"\"\"Populate the DB with sample vendors, orders, and vendor/analyst\n        logins so the dashboards have something to show. Safe to run\n        repeatedly — skips if vendors already exist.\n        \"\"\"\n        import random\n        from datetime import timedelta\n\n        from werkzeug.security import generate_password_hash\n\n        from app.extensions import db\n        from app.models import Order, User, UserRole, Vendor\n\n        if Vendor.query.first():\n            print(\"Vendors already exist — skipping demo data seed.\")\n            return\n\n        vendor_names = [\"Northwind Traders\", \"Aarohi Textiles\", \"Blue Ridge Goods\"]\n        vendors = []\n        for name in vendor_names:\n            v = Vendor(name=name, slug=name.lower().replace(\" \", \"-\"), is_active=True)\n            db.session.add(v)\n            vendors.append(v)\n        db.session.flush()  # assigns vendor.id without a full commit\n\n        statuses = [\"pending\", \"paid\", \"shipped\", \"failed\"]\n        for i in range(30):\n            vendor = random.choice(vendors)\n            order = Order(\n                vendor_id=vendor.id,\n                external_order_id=f\"DEMO-{1000 + i}\",\n                amount_inr=round(random.uniform(500, 15000), 2),\n                status=random.choice(statuses),\n                created_at=datetime.utcnow() - timedelta(days=random.randint(0, 30)),\n            )\n            db.session.add(order)\n\n        vendor_user = User(\n            email=\"vendor@example.com\",\n            password_hash=generate_password_hash(\"VendorDemo123\"),\n            role=UserRole.VENDOR,\n            vendor_id=vendors[0].id,\n        )\n        analyst_user = User(\n            email=\"analyst@example.com\",\n            password_hash=generate_password_hash(\"AnalystDemo123\"),\n            role=UserRole.ANALYST,\n        )\n        db.session.add_all([vendor_user, analyst_user])\n        db.session.commit()\n        print(f\"Seeded {len(vendors)} vendors, 30 orders, and vendor/analyst logins.\")\n\n\ndef _register_blueprints(app: Flask) -> None:\n    from app.auth.routes import auth_bp\n    from app.blueprints.admin.routes import admin_bp\n    from app.blueprints.analyst.routes import analyst_bp\n    from app.blueprints.ml.routes import ml_bp\n    from app.blueprints.vendor.routes import vendor_bp\n    from app.webhooks.routes import webhooks_bp\n\n    app.register_blueprint(auth_bp)\n    app.register_blueprint(admin_bp)\n    app.register_blueprint(vendor_bp)\n    app.register_blueprint(analyst_bp)\n    app.register_blueprint(ml_bp)\n    app.register_blueprint(webhooks_bp)\n"}, {"title": "Pandas ETL", "path": "multi-vendor-e-commerce-main/backend/app/etl/vendors_etl.py", "code": "\"\"\"Pandas ETL: cleans and aggregates raw per-vendor order/inventory CSV exports\ninto a unified weekly analytics dataset.\n\nReplaces a previously manual ~2 FTE-day weekly reporting process.\n\"\"\"\n\nimport glob\nimport os\n\nimport pandas as pd\n\nRAW_EXPORTS_DIR = os.environ.get(\"VENDOR_RAW_EXPORTS_DIR\", \"data/raw_exports\")\nOUTPUT_DIR = os.environ.get(\"VENDOR_ETL_OUTPUT_DIR\", \"data/processed\")\n\nEXPECTED_ORDER_COLUMNS = [\n    \"vendor_id\", \"order_id\", \"sku\", \"quantity\", \"unit_price_inr\", \"order_date\", \"status\",\n]\n\n\ndef _load_vendor_csv(path: str) -> pd.DataFrame:\n    df = pd.read_csv(path)\n    df.columns = [c.strip().lower().replace(\" \", \"_\") for c in df.columns]\n    missing = set(EXPECTED_ORDER_COLUMNS) - set(df.columns)\n    if missing:\n        raise ValueError(f\"{path} missing expected columns: {missing}\")\n    return df\n\n\ndef _clean(df: pd.DataFrame) -> pd.DataFrame:\n    df = df.drop_duplicates(subset=[\"vendor_id\", \"order_id\", \"sku\"])\n    df[\"order_date\"] = pd.to_datetime(df[\"order_date\"], errors=\"coerce\")\n    df = df.dropna(subset=[\"order_date\"])\n    df[\"quantity\"] = pd.to_numeric(df[\"quantity\"], errors=\"coerce\").fillna(0)\n    df[\"unit_price_inr\"] = pd.to_numeric(df[\"unit_price_inr\"], errors=\"coerce\").fillna(0)\n    df[\"line_total_inr\"] = df[\"quantity\"] * df[\"unit_price_inr\"]\n    df[\"status\"] = df[\"status\"].str.strip().str.lower()\n    return df\n\n\ndef run_weekly_aggregation(vendor_id: int | None = None) -> pd.DataFrame:\n    \"\"\"Loads all raw vendor CSVs, cleans them, and returns a per-vendor weekly summary.\n\n    Also writes the aggregated dataset to OUTPUT_DIR as CSV for downstream reporting.\n    \"\"\"\n    csv_paths = glob.glob(os.path.join(RAW_EXPORTS_DIR, \"*.csv\"))\n    if not csv_paths:\n        return pd.DataFrame(columns=[\"vendor_id\", \"week\", \"orders\", \"units_sold\", \"revenue_inr\"])\n\n    frames = [_clean(_load_vendor_csv(p)) for p in csv_paths]\n    combined = pd.concat(frames, ignore_index=True)\n\n    if vendor_id is not None:\n        combined = combined[combined[\"vendor_id\"] == vendor_id]\n\n    combined[\"week\"] = combined[\"order_date\"].dt.to_period(\"W\").astype(str)\n\n    summary = (\n        combined.groupby([\"vendor_id\", \"week\"])\n        .agg(\n            orders=(\"order_id\", \"nunique\"),\n            units_sold=(\"quantity\", \"sum\"),\n            revenue_inr=(\"line_total_inr\", \"sum\"),\n            failed_orders=(\"status\", lambda s: (s == \"failed\").sum()),\n        )\n        .reset_index()\n        .sort_values([\"vendor_id\", \"week\"])\n    )\n\n    os.makedirs(OUTPUT_DIR, exist_ok=True)\n    out_path = os.path.join(OUTPUT_DIR, \"weekly_vendor_summary.csv\")\n    summary.to_csv(out_path, index=False)\n\n    return summary\n"}, {"title": "ML feature engineering", "path": "multi-vendor-e-commerce-main/backend/app/ml/features.py", "code": "\"\"\"Feature engineering for the ML pipeline.\n\nDeliberately built as a thin layer on top of the existing ETL\n(``app.etl.vendors_etl.run_weekly_aggregation``) rather than a parallel\ndata path — the weekly vendor summary is already cleaned/deduped, so\nevery model in ``app.ml`` reuses it instead of re-reading raw CSVs.\n\nTwo feature tables are produced:\n\n- ``build_vendor_week_features`` — one row per (vendor, week), with lag\n  and rolling-window features for demand forecasting and vendor scoring.\n- ``build_order_features`` — one row per order, with per-vendor z-scores\n  and time-of-day features for anomaly/fraud scoring.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nfrom app.etl.vendors_etl import run_weekly_aggregation\n\nLAG_COLUMNS = [\"revenue_inr\", \"units_sold\", \"orders\"]\n\n\ndef build_vendor_week_features(vendor_id: int | None = None) -> pd.DataFrame:\n    \"\"\"Weekly vendor features: lag-1 and trailing 3-week rolling averages.\n\n    Lags are computed per-vendor so one vendor's history never leaks into\n    another's features. The first 1-2 weeks per vendor will have lag/\n    rolling values backfilled to 0 (handled via ``fillna``) since there's\n    no prior history yet — acceptable for a model trained on many weeks.\n    \"\"\"\n    df = run_weekly_aggregation(vendor_id=vendor_id)\n    if df.empty:\n        return df\n\n    df = df.sort_values([\"vendor_id\", \"week\"]).reset_index(drop=True)\n    df[\"week_index\"] = df.groupby(\"vendor_id\").cumcount()\n\n    for col in LAG_COLUMNS:\n        df[f\"{col}_lag1\"] = df.groupby(\"vendor_id\")[col].shift(1)\n        df[f\"{col}_rolling3\"] = df.groupby(\"vendor_id\")[col].transform(\n            lambda s: s.shift(1).rolling(3, min_periods=1).mean()\n        )\n\n    df[\"failed_rate\"] = (\n        df[\"failed_orders\"] / df[\"orders\"].replace(0, np.nan)\n    ).fillna(0)\n\n    return df.fillna(0)\n\n\ndef build_order_features(orders_df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"Order-level features for anomaly detection.\n\n    Expects columns: vendor_id, amount_inr, created_at, status.\n    Adds a per-vendor amount z-score, since \"unusual\" only means\n    something relative to a vendor's own typical order size — a ₹50,000\n    order is routine for one vendor and wildly anomalous for another.\n    \"\"\"\n    df = orders_df.copy()\n    df[\"created_at\"] = pd.to_datetime(df[\"created_at\"])\n    df[\"hour\"] = df[\"created_at\"].dt.hour\n    df[\"day_of_week\"] = df[\"created_at\"].dt.dayofweek\n\n    vendor_stats = (\n        df.groupby(\"vendor_id\")[\"amount_inr\"]\n        .agg([\"mean\", \"std\"])\n        .rename(columns={\"mean\": \"vendor_mean_amount\", \"std\": \"vendor_std_amount\"})\n    )\n    df = df.merge(vendor_stats, on=\"vendor_id\", how=\"left\")\n    df[\"vendor_std_amount\"] = df[\"vendor_std_amount\"].fillna(0)\n\n    denom = df[\"vendor_std_amount\"].replace(0, np.nan)\n    df[\"amount_zscore\"] = ((df[\"amount_inr\"] - df[\"vendor_mean_amount\"]) / denom).fillna(0)\n\n    return df\n"}, {"title": "Webhook routes", "path": "multi-vendor-e-commerce-main/backend/app/webhooks/routes.py", "code": "from flask import Blueprint, current_app, jsonify, request\n\nfrom app.extensions import db\nfrom app.integrations import sendgrid_service, stripe_service\nfrom app.models import Order, WebhookEvent\n\nwebhooks_bp = Blueprint(\"webhooks\", __name__, url_prefix=\"/api/webhooks\")\n\n\ndef _already_processed(source: str, event_id: str) -> bool:\n    \"\"\"Idempotency guard: skip work if we've already recorded this event_id.\"\"\"\n    return WebhookEvent.query.filter_by(source=source, event_id=event_id).first() is not None\n\n\ndef _mark_processed(source: str, event_id: str):\n    db.session.add(WebhookEvent(source=source, event_id=event_id))\n    db.session.commit()\n\n\n@webhooks_bp.post(\"/stripe\")\ndef stripe_webhook():\n    payload = request.get_data()\n    sig_header = request.headers.get(\"Stripe-Signature\")\n\n    try:\n        event = stripe_service.verify_webhook_signature(payload, sig_header)\n    except Exception as exc:  # signature/verification failure\n        current_app.logger.warning(\"Stripe webhook verification failed: %s\", exc)\n        return jsonify(error=\"invalid signature\"), 400\n\n    if _already_processed(\"stripe\", event[\"id\"]):\n        return jsonify(status=\"already_processed\"), 200\n\n    if event[\"type\"] == \"payment_intent.succeeded\":\n        intent = event[\"data\"][\"object\"]\n        order_id = intent[\"metadata\"].get(\"order_id\")\n        order = Order.query.filter_by(external_order_id=order_id).first()\n        if order:\n            order.status = \"paid\"\n            order.payment_intent_id = intent[\"id\"]\n            db.session.commit()\n            sendgrid_service.send_templated_email(\n                to_email=intent.get(\"receipt_email\", \"\"),\n                template_key=\"order_confirmation\",\n                dynamic_data={\"order_id\": order_id},\n            )\n\n    _mark_processed(\"stripe\", event[\"id\"])\n    return jsonify(status=\"ok\"), 200\n\n\n@webhooks_bp.post(\"/shiprocket\")\ndef shiprocket_webhook():\n    data = request.get_json(silent=True) or {}\n    event_id = data.get(\"event_id\") or f\"{data.get('shipment_id')}-{data.get('status')}\"\n\n    if _already_processed(\"shiprocket\", event_id):\n        return jsonify(status=\"already_processed\"), 200\n\n    shipment_id = data.get(\"shipment_id\")\n    order = Order.query.filter_by(shipment_id=shipment_id).first()\n    if order:\n        order.status = data.get(\"status\", order.status)\n        db.session.commit()\n        sendgrid_service.send_templated_email(\n            to_email=data.get(\"customer_email\", \"\"),\n            template_key=\"shipment_update\",\n            dynamic_data={\"status\": order.status, \"shipment_id\": shipment_id},\n        )\n\n    _mark_processed(\"shiprocket\", event_id)\n    return jsonify(status=\"ok\"), 200\n"}], "netlist": [{"title": "Recursive SPICE parser", "path": "netlist-parser-main/include/NetlistParser.h", "code": "#pragma once\n#include \"Subcircuit.h\"\n#include <fstream>\n#include <iostream>\n#include <memory>\n#include <sstream>\n#include <stdexcept>\n#include <string>\n#include <vector>\n\n// Parses a minimal SPICE-format netlist into a Subcircuit object model.\n// Supported element lines:\n//   R<name> <nodeA> <nodeB> <value>        -- Resistor\n//   C<name> <nodeA> <nodeB> <value>        -- Capacitor\n//   M<name> <drain> <gate> <source> <bulk> <NMOS|PMOS>  -- MOSFET\nclass NetlistParser {\npublic:\n    // Parse file at path; throws std::runtime_error on failure\n    std::unique_ptr<Subcircuit> parse(const std::string& filepath) {\n        std::ifstream file(filepath);\n        if (!file.is_open())\n            throw std::runtime_error(\"Cannot open netlist: \" + filepath);\n\n        // Use filename (without extension) as subcircuit name\n        std::string subcktName = filepath;\n        auto slash = subcktName.find_last_of(\"/\\\\\");\n        if (slash != std::string::npos) subcktName = subcktName.substr(slash + 1);\n        auto dot = subcktName.rfind('.');\n        if (dot != std::string::npos) subcktName = subcktName.substr(0, dot);\n\n        auto subckt = std::make_unique<Subcircuit>(subcktName);\n\n        std::string line;\n        int lineNo = 0;\n        while (std::getline(file, line)) {\n            ++lineNo;\n            // Strip comments and blank lines\n            auto commentPos = line.find('*');\n            if (commentPos != std::string::npos) line = line.substr(0, commentPos);\n            if (line.find_first_not_of(\" \\t\\r\\n\") == std::string::npos) continue;\n\n            try {\n                parseLine(line, *subckt);\n            } catch (const std::exception& e) {\n                std::cerr << \"Warning: line \" << lineNo << \" skipped — \" << e.what() << \"\\n\";\n            }\n        }\n        return subckt;\n    }\n\nprivate:\n    std::vector<std::string> tokenize(const std::string& line) {\n        std::istringstream iss(line);\n        std::vector<std::string> tokens;\n        std::string tok;\n        while (iss >> tok) tokens.push_back(tok);\n        return tokens;\n    }\n\n    void parseLine(const std::string& line, Subcircuit& subckt) {\n        auto tokens = tokenize(line);\n        if (tokens.empty()) return;\n\n        const char prefix = static_cast<char>(std::toupper(tokens[0][0]));\n\n        if (prefix == 'R') {\n            if (tokens.size() < 4)\n                throw std::runtime_error(\"Resistor needs 4 fields: R<name> nodeA nodeB value\");\n            double val = std::stod(tokens[3]);\n            subckt.addComponent(\n                std::make_unique<Resistor>(tokens[0], tokens[1], tokens[2], val));\n\n        } else if (prefix == 'C') {\n            if (tokens.size() < 4)\n                throw std::runtime_error(\"Capacitor needs 4 fields: C<name> nodeA nodeB value\");\n            double val = std::stod(tokens[3]);\n            subckt.addComponent(\n                std::make_unique<Capacitor>(tokens[0], tokens[1], tokens[2], val));\n\n        } else if (prefix == 'M') {\n            if (tokens.size() < 6)\n                throw std::runtime_error(\"MOSFET needs 6 fields: M<name> drain gate source bulk type\");\n            std::string mtype = tokens[5];\n            for (auto& c : mtype) c = static_cast<char>(std::toupper(c));\n            Mosfet::Channel ch = (mtype == \"PMOS\") ? Mosfet::Channel::PMOS\n                                                    : Mosfet::Channel::NMOS;\n            subckt.addComponent(\n                std::make_unique<Mosfet>(tokens[0], tokens[1], tokens[2],\n                                         tokens[3], tokens[4], ch));\n        } else {\n            // Unknown prefix — skip silently (e.g. .subckt, .ends, .tran)\n        }\n    }\n};\n"}, {"title": "Component hierarchy", "path": "netlist-parser-main/include/component.h", "code": "#pragma once\n#include <string>\n#include <vector>\n\n// Forward declaration for Visitor pattern\nclass CircuitVisitor;\n\n// Abstract base class for all circuit components\nclass Component {\npublic:\n    Component(const std::string& name, const std::vector<std::string>& pins)\n        : name_(name), pins_(pins) {}\n\n    virtual ~Component() = default;\n\n    virtual std::string type() const = 0;\n    virtual void accept(CircuitVisitor& visitor) const = 0;\n\n    const std::string& name() const { return name_; }\n    const std::vector<std::string>& pins() const { return pins_; }\n\nprotected:\n    std::string name_;\n    std::vector<std::string> pins_;\n};\n\nclass Resistor : public Component {\npublic:\n    Resistor(const std::string& name, const std::string& nodeA,\n             const std::string& nodeB, double ohms)\n        : Component(name, {nodeA, nodeB}), ohms_(ohms) {}\n\n    std::string type() const override { return \"Resistor\"; }\n    void accept(CircuitVisitor& visitor) const override;\n    double resistance() const { return ohms_; }\n\nprivate:\n    double ohms_;\n};\n\nclass Capacitor : public Component {\npublic:\n    Capacitor(const std::string& name, const std::string& nodeA,\n              const std::string& nodeB, double farads)\n        : Component(name, {nodeA, nodeB}), farads_(farads) {}\n\n    std::string type() const override { return \"Capacitor\"; }\n    void accept(CircuitVisitor& visitor) const override;\n    double capacitance() const { return farads_; }\n\nprivate:\n    double farads_;\n};\n\nclass Mosfet : public Component {\npublic:\n    enum class Channel { NMOS, PMOS };\n\n    Mosfet(const std::string& name, const std::string& drain,\n           const std::string& gate, const std::string& source,\n           const std::string& bulk, Channel ch)\n        : Component(name, {drain, gate, source, bulk}), channel_(ch) {}\n\n    std::string type() const override {\n        return channel_ == Channel::NMOS ? \"NMOS\" : \"PMOS\";\n    }\n    void accept(CircuitVisitor& visitor) const override;\n    Channel channel() const { return channel_; }\n\nprivate:\n    Channel channel_;\n};\n"}, {"title": "Composite container", "path": "netlist-parser-main/include/Subcircuit.h", "code": "#pragma once\n#include \"component.h\"\n#include \"net.h\"\n#include <memory>\n#include <string>\n#include <unordered_map>\n#include <vector>\n\n// Composite: owns components and nets, models a .subckt block\nclass Subcircuit {\npublic:\n    explicit Subcircuit(const std::string& name) : name_(name) {}\n\n    // Add a component; Subcircuit takes ownership\n    void addComponent(std::unique_ptr<Component> comp) {\n        // Register component pins onto their nets\n        for (const auto& pin : comp->pins()) {\n            nets_[pin].addConnection(comp->name(), pin);\n        }\n        components_.push_back(std::move(comp));\n    }\n\n    const std::string& name() const { return name_; }\n\n    const std::vector<std::unique_ptr<Component>>& components() const {\n        return components_;\n    }\n\n    const std::unordered_map<std::string, Net>& nets() const { return nets_; }\n\n    // Returns the net with highest fanout\n    const Net* highestFanoutNet() const {\n        const Net* best = nullptr;\n        for (const auto& [netName, net] : nets_) {\n            if (!best || net.fanout() > best->fanout())\n                best = &net;\n        }\n        return best;\n    }\n\nprivate:\n    std::string name_;\n    std::vector<std::unique_ptr<Component>> components_;\n    std::unordered_map<std::string, Net> nets_;\n};\n"}, {"title": "Visitor analyzer", "path": "netlist-parser-main/include/Analyzer.h", "code": "#pragma once\n#include \"component.h\"\n#include \"Subcircuit.h\"\n#include <iostream>\n#include <map>\n#include <string>\n\n// Visitor interface — decouples analysis from the component hierarchy\nclass CircuitVisitor {\npublic:\n    virtual ~CircuitVisitor() = default;\n    virtual void visit(const Resistor& r) = 0;\n    virtual void visit(const Capacitor& c) = 0;\n    virtual void visit(const Mosfet& m) = 0;\n};\n\n// Concrete visitor: counts components by type and reports circuit stats\nclass Analyzer : public CircuitVisitor {\npublic:\n    void visit(const Resistor&)  override { counts_[\"Resistor\"]++; }\n    void visit(const Capacitor&) override { counts_[\"Capacitor\"]++; }\n    void visit(const Mosfet& m)  override { counts_[m.type()]++; }\n\n    void analyze(const Subcircuit& sub) {\n        std::cout << \"\\n=== Netlist Report: \" << sub.name() << \" ===\\n\";\n\n        // Run visitor over every component\n        for (const auto& comp : sub.components())\n            comp->accept(*this);\n\n        // Component census\n        std::cout << \"\\nComponent counts:\\n\";\n        int total = 0;\n        for (const auto& [type, count] : counts_) {\n            std::cout << \"  \" << type << \": \" << count << \"\\n\";\n            total += count;\n        }\n        std::cout << \"  TOTAL: \" << total << \"\\n\";\n\n        // Net statistics\n        std::cout << \"\\nNet count: \" << sub.nets().size() << \"\\n\";\n\n        if (const Net* top = sub.highestFanoutNet()) {\n            std::cout << \"Highest fanout net: \\\"\" << top->name()\n                      << \"\\\"  fanout=\" << top->fanout() << \"\\n\";\n        }\n        std::cout << \"===========================\\n\";\n    }\n\nprivate:\n    std::map<std::string, int> counts_;\n};\n"}, {"title": "CLI entry point", "path": "netlist-parser-main/src/main.cpp", "code": "#include \"NetlistParser.h\"\n#include \"Analyzer.h\"\n#include <iostream>\n\nint main(int argc, char* argv[]) {\n    std::string filepath = \"circuits/inverter.sp\";\n    if (argc > 1) filepath = argv[1];\n\n    std::cout << \"NetlistParser — EDA Circuit Analyzer\\n\";\n    std::cout << \"Parsing: \" << filepath << \"\\n\";\n\n    try {\n        NetlistParser parser;\n        auto subckt = parser.parse(filepath);\n\n        Analyzer analyzer;\n        analyzer.analyze(*subckt);\n    } catch (const std::exception& e) {\n        std::cerr << \"Error: \" << e.what() << \"\\n\";\n        return 1;\n    }\n\n    return 0;\n}\n"}, {"title": "CMake build", "path": "netlist-parser-main/CMakeLists.txt", "code": "cmake_minimum_required(VERSION 3.15)\nproject(NetlistParser VERSION 1.0 LANGUAGES CXX)\n\nset(CMAKE_CXX_STANDARD 17)\nset(CMAKE_CXX_STANDARD_REQUIRED ON)\n\ninclude_directories(include)\n\nadd_executable(netlist_parser\n    src/main.cpp\n    src/Component.cpp\n)\n\n# Enable warnings\ntarget_compile_options(netlist_parser PRIVATE\n    $<$<CXX_COMPILER_ID:GNU,Clang>:-Wall -Wextra -Wpedantic>\n    $<$<CXX_COMPILER_ID:MSVC>:/W4>\n)\n"}]};
